const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch({
    headless: false,
    executablePath: 'C:\\Users\\Administrator\\AppData\\Local\\Google\\Chrome\\Application\\chrome.exe'
  });

  const context = await browser.newContext();
  const page = await context.newPage();

  // Navigate to login page
  await page.goto('https://gez.dongguanbank.cn/landlord/#/login');

  // Wait for page to load
  await page.waitForLoadState('networkidle');

  // Take a screenshot to see the page
  await page.screenshot({ path: 'login_page.png' });
  console.log('Page loaded, screenshot saved');

  // Try to find and fill username field
  try {
    // Common selectors for username field
    const usernameSelectors = [
      'input[type="text"]',
      'input[placeholder*="账号"]',
      'input[placeholder*="用户名"]',
      'input[placeholder*="手机"]',
      'input[name="username"]',
      'input[name="account"]',
      '.el-input__inner[type="text"]',
      'input.el-input__inner'
    ];

    let usernameField = null;
    for (const selector of usernameSelectors) {
      try {
        usernameField = await page.locator(selector).first();
        if (await usernameField.isVisible({ timeout: 2000 })) {
          console.log(`Found username field with selector: ${selector}`);
          break;
        }
      } catch (e) {
        continue;
      }
    }

    if (usernameField) {
      await usernameField.fill('18926879306');
      console.log('Username filled');
    }

    // Try to find and fill password field
    const passwordSelectors = [
      'input[type="password"]',
      'input[name="password"]',
      'input[placeholder*="密码"]',
      '.el-input__inner[type="password"]',
      'input.el-input__inner'
    ];

    let passwordField = null;
    for (const selector of passwordSelectors) {
      try {
        passwordField = await page.locator(selector).first();
        if (await passwordField.isVisible({ timeout: 2000 })) {
          console.log(`Found password field with selector: ${selector}`);
          break;
        }
      } catch (e) {
        continue;
      }
    }

    if (passwordField) {
      await passwordField.fill('100911yzpYZP');
      console.log('Password filled');
    }

    // Take a screenshot after filling
    await page.screenshot({ path: 'login_filled.png' });
    console.log('Screenshot after filling saved');

    // Wait a bit to see the result
    await page.waitForTimeout(2000);

  } catch (error) {
    console.error('Error:', error.message);
    await page.screenshot({ path: 'error_page.png' });
    console.log('Error screenshot saved');
  }

  // Don't close browser immediately, let user see the result
  await browser.close();
})();

const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch({
    headless: false,
    executablePath: 'C:\\Users\\Administrator\\AppData\\Local\\Google\\Chrome\\Application\\chrome.exe'
  });

  const context = await browser.newContext();
  const page = await context.newPage();

  // Navigate to login page
  await page.goto('https://gez.dongguanbank.cn/landlord/#/login');
  await page.waitForLoadState('networkidle');

  // Fill username
  try {
    await page.locator('input[type="text"]').first().fill('18926879306');
    console.log('Username filled');
  } catch (e) {
    console.log('Could not fill username:', e.message);
  }

  // Fill password
  try {
    await page.locator('input[type="password"]').first().fill('100911yzpYZP');
    console.log('Password filled');
  } catch (e) {
    console.log('Could not fill password:', e.message);
  }

  await page.waitForTimeout(500);

  // Try to click login button
  try {
    const loginButtonSelectors = [
      'button[type="submit"]',
      'button:has-text("登录")',
      '.el-button--primary',
      'button.el-button',
      '.login-btn',
      'a:has-text("登录")',
      'input[type="submit"]'
    ];

    for (const selector of loginButtonSelectors) {
      try {
        const btn = await page.locator(selector).first();
        if (await btn.isVisible({ timeout: 2000 })) {
          await btn.click();
          console.log(`Clicked login button with selector: ${selector}`);
          break;
        }
      } catch (e) {
        continue;
      }
    }
  } catch (e) {
    console.log('Could not click login button:', e.message);
  }

  // Wait for navigation after login
  await page.waitForTimeout(3000);

  // Take final screenshot
  await page.screenshot({ path: 'after_login.png', fullPage: true });
  console.log('Final screenshot saved');

  // Close browser after a delay
  await page.waitForTimeout(2000);

